// ГРАНИЦА, а не канон. `no-destructure` ловит деструктуризацию только в списке параметров;
// эта — в теле функции, и его правило НЕ видит. Файл существует, чтобы дыра была
// зафиксирована тестом, а не жила преданием: тест сверяет, какие правила здесь срабатывают
// на самом деле, и падает, если ответ изменится выпуском плагина.
export function Greeting(props: { name: string }) {
  const { name } = props;

  return <h1>{name}</h1>;
}
